lanalto.gov.br/ccivil_03/_ato2023-2026/2025/lei/l15263.htm","bytes":23755,"sha256":"02913b7878a102065327dfd6311a16963177d07d713d4e64fcc738836430a165","checked_at":"2026-10-25T02:44:54.076624+00:00","title":"Lei 15.263/2025 — Política Nacional de Linguagem Simples","id":"a16f97a9-7481-5d77-9bf8-3da8b0599e2d","status":"vigente","is_official":true,"source_type":"lei","issuer":"Presidência da República — Planalto"},{"key":"concordancia","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/concordancia-verbal","sha256":"0ce86a5c31bae99702af0e93eace32547442022cfd7f3a310108b4e2097a808e","checked_at":"2026-10-25T02:47:55.585610+00:00","bytes":26884,"title":"Senado Federal — concordância verbal","id":"421bb930-7b5a-5f24-9597-651fbf2ba62e","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"key":"crase","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/crase","sha256":"a68488bead83950f65170fa13713bf47a69aea64bf894b4d05262bd50e65dbe1","checked_at":"2026-10-25T02:47:56.606572+00:00","bytes":24413,"title":"Senado Federal — crase","id":"1e2fd682-059c-5a08-b8ed-416cc61441fc","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"key":"virgula","url":"https://www12.senado.leg.br/manualdecomunicacao/estilos/virgula","sha256":"149b64227e4d08c429f1ac80c58db59cc85cc545e3d5a1a7ca3fef750fa7d438","checked_at":"2026-10-25T02:49:16.178595+00:00","bytes":21809,"title":"Senado Federal — uso da vírgula","id":"f86cce8d-00f6-5d75-87db-fd05ef272a07","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","bytes":24352,"sha256":"c9d716829969122d7e63a48e49c127f81993a55dc2c343b0a1fb44889ccce03b","checked_at":"2026-10-25T03:07:02.833711+00:00","key":"gramatica","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","id":"8839c291-1d0d-554e-b02a-72a35ac278b4","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"},{"url":"https://cdn.cebraspe.org.br/concursos/PF_25/arquivos/Ed_1_PF_25_Abertura_Atualizado_ate_ret_4.pdf","sha256":"900be3d17f0a8f6e834d2c90019e3a594aa0fa81d354fff483059662401be88b","checked_at":"2026-10-25T02:47:05.911646+00:00","key":"edital","title":"Polícia Federal — Agente — Edital 1/2025 e retificações","id":"e48e61a0-ecf6-4140-b431-e9dba7b40b67","status":"vigente","is_official":true,"source_type":"edital","issuer":"Polícia Federal / Cebraspe"}],"rows":[{"kind":"new","key":"leitura","topic":{"id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Compreensão e interpretação de textos de gêneros variados; reconhecimento de tipos e gêneros textuais; domínio da ortografia oficial e dos mecanismos de coesão textual; referenciação, substituição, repetição, conectores e sequenciação; tempos e modos verbais.","topic_order":1,"content_status":"current"},"material":{"id":"dbb295b6-75e8-55ea-bb20-494b3fc39ea2","slug":"portugues-leitura-interpretacao-tipologia","discipline":"Língua Portuguesa","topic_label":"Interpretação e tipologia textual","sort_order":10,"title":"Leitura e tipologia: interpretação, inferência e gêneros textuais","summary":"Conceitos essenciais, exemplos próprios, caso resolvido e vinte exercícios comentados. Integra o percurso de Português sem reproduzir capítulos já publicados.","body_md":"## O texto limita a resposta\n\nCompreender é recuperar informações expressas e relações construídas no texto. Inferir é concluir algo sustentado por pistas, não acrescentar opinião ou uma informação apenas plausível no mundo. Identifique autor, interlocutor, finalidade, situação de circulação e comando da questão. Uma alternativa pode ser verdadeira e ainda não responder ao que o trecho permite concluir.\n\nEm “A biblioteca passou a abrir aos domingos, mas a frequência não aumentou”, o contraste está entre a ampliação do acesso e o resultado observado. Não se pode concluir, só daí, que nenhum estudante goste de ler. Quantificadores como todos, alguns e nenhum mudam o alcance da informação; hipótese não equivale a certeza.\n\n## Tipo não é gênero\n\n| Organização predominante | Indício útil |\n| --- | --- |\n| Narração | Acontecimentos e transformações no tempo |\n| Descrição | Caracterização de pessoa, objeto, ambiente ou estado |\n| Exposição | Apresentação e explicação de informações |\n| Argumentação | Defesa de um ponto de vista com razões |\n| Injunção | Orientação para realizar uma ação |\n\nNotícia, relatório, anúncio e conto são gêneros situados socialmente. Um gênero pode combinar sequências narrativas, descritivas e argumentativas; não classifique um texto inteiro por uma palavra isolada. Verbos no passado são um indício possível de narração, não uma prova suficiente.\n\n## Implícitos, vozes e reescrita\n\nEm “A unidade voltou a atender”, a expressão voltou a pressupõe atendimento anterior interrompido. Uma ironia pode opor o sentido literal à avaliação sugerida pelo contexto; ela não deve ser afirmada sem evidência. Distinguir fala do autor, citação e ponto de vista de uma personagem evita atribuições erradas.\n\nCompare o conteúdo original e a alternativa: referente, negação, intensidade, tempo, modalidade e relação lógica. Para os mecanismos de ligação, continue em [Coesão e reescrita](/dashboard/library/portugues-coesao-reescrita-sentido). O material do ENEM permanece em sua área própria; este percurso é de preparação geral para concursos.\n","contest_name":"Polícia Federal — Agente de Polícia Federal — 2025","syllabus_topic_order":1,"source_note":"Elaboração didática própria a partir dos temas dos arquivos fornecidos e de referências institucionais de uso formal e ortografia. Não republica integralmente a redação, publicidade, nomes de docentes ou diagramação das apostilas. Exercícios do acervo têm sua procedência identificada separadamente. Conceitos gramaticais não são apresentados como texto literal de lei. A aplicação a cada concurso depende do edital e de sua data de corte.","legal_basis":[{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal"}],"law_version_checked_at":"2026-10-25T03:23:26.419620+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-25T03:23:26.419620+00:00","quiz":[{"q":"Uma inferência válida precisa de apoio nas informações e relações construídas no texto.","a":true,"why":"Inferir não é criar uma explicação apenas possível fora do texto."},{"q":"Uma alternativa verdadeira no mundo necessariamente responde corretamente à interpretação de qualquer texto.","a":false,"why":"A resposta deve atender ao comando e às evidências do trecho."},{"q":"A presença de um verbo no passado basta para classificar qualquer texto como narrativo.","a":false,"why":"É necessário examinar sua organização predominante e sua finalidade."},{"q":"Um gênero textual pode combinar sequências descritivas, narrativas e argumentativas.","a":true,"why":"Tipo e gênero são classificações de planos distintos."},{"q":"Notícia e narração são nomes da mesma categoria classificatória.","a":false,"why":"Notícia designa gênero; narração, uma organização textual."},{"q":"Em 'A biblioteca voltou a abrir', a expressão 'voltou a' pressupõe abertura anterior.","a":true,"why":"A construção indica retomada de uma situação."},{"q":"Substituir 'alguns servidores' por 'todos os servidores' sempre preserva a informação.","a":false,"why":"A troca altera o alcance da afirmação."},{"q":"Em 'Estude, mas reserve tempo para descansar', 'mas' introduz contraste.","a":true,"why":"A relação deve ser identificada no contexto, não por simples proximidade."},{"q":"Toda opinião de uma personagem pode ser atribuída diretamente ao autor do texto.","a":false,"why":"Vozes e posições enunciativas precisam ser distinguidas."},{"q":"Uma descrição pode caracterizar ambiente sem apresentar progressão de acontecimentos.","a":true,"why":"A caracterização é indício descritivo, não necessariamente narrativo."},{"q":"Um manual de instruções tende a conter sequências de orientação para agir.","a":true,"why":"A função injuntiva se relaciona à condução de ações."},{"q":"Toda informação implícita é uma opinião livre do leitor.","a":false,"why":"Implícitos dependem de marcas e relações do texto."},{"q":"Na argumentação, exemplos podem apoiar uma tese sem se confundirem com ela.","a":true,"why":"Distinguir ponto de vista e sua sustentação evita troca de funções."},{"q":"A tese sempre aparece obrigatoriamente na primeira frase do texto.","a":false,"why":"A posição pode ser apresentada ou construída em diferentes lugares."},{"q":"O interlocutor e a situação de circulação ajudam a compreender a finalidade do texto.","a":true,"why":"O contexto comunicativo participa da interpretação."},{"q":"Uma frase gramaticalmente correta sempre mantém o sentido da frase que substitui.","a":false,"why":"Correção gramatical e equivalência semântica são critérios diferentes."},{"q":"Transformar uma hipótese em certeza pode alterar o sentido de uma reescrita.","a":true,"why":"Modalidade e grau de comprometimento com a afirmação importam."},{"q":"A ironia pode ser identificada com segurança sem considerar o contexto.","a":false,"why":"O efeito depende do contraste entre enunciado e avaliação sugerida."},{"q":"O comando 'de acordo com o texto' restringe a resposta ao apoio textual pertinente.","a":true,"why":"Conhecimento externo não autoriza substituir o que o texto afirma."},{"q":"Negação, quantificadores e relações temporais merecem conferência na reescrita.","a":true,"why":"Pequenas mudanças nesses elementos podem modificar a informação."}],"flashcards":[{"f":"Uma inferência válida precisa de apoio nas informações e relações construídas no texto.","b":"Certo. Inferir não é criar uma explicação apenas possível fora do texto."},{"f":"Uma alternativa verdadeira no mundo necessariamente responde corretamente à interpretação de qualquer texto.","b":"Errado. A resposta deve atender ao comando e às evidências do trecho."},{"f":"A presença de um verbo no passado basta para classificar qualquer texto como narrativo.","b":"Errado. É necessário examinar sua organização predominante e sua finalidade."},{"f":"Um gênero textual pode combinar sequências descritivas, narrativas e argumentativas.","b":"Certo. Tipo e gênero são classificações de planos distintos."}],"legal_review":null,"practice_review":{"version":1,"status":"reviewed","material_slug":"portugues-leitura-interpretacao-tipologia","subject":"Língua Portuguesa","topic_label":"Interpretação e tipologia textual","syllabus_topic_id":"2ab9d0f8-22f6-467b-bb30-cd0c5cff4b7f","checked_at":"2026-10-25T03:23:26.419620+00:00","scope":"Revisão didática assistida dos vinte exercícios. Conceitos e exemplos elaborados para aprendizagem; referências institucionais orientam ortografia e uso formal, sem alegação de transcrição literal de todos os conceitos no manual.","sources":[{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","bytes":24352,"sha256":"c9d716829969122d7e63a48e49c127f81993a55dc2c343b0a1fb44889ccce03b","checked_at":"2026-10-25T03:07:02.833711+00:00","key":"gramatica","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","id":"8839c291-1d0d-554e-b02a-72a35ac278b4","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"}],"items":[{"q":"Uma inferência válida precisa de apoio nas informações e relações construídas no texto.","a":true,"why":"Inferir não é criar uma explicação apenas possível fora do texto.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Uma alternativa verdadeira no mundo necessariamente responde corretamente à interpretação de qualquer texto.","a":false,"why":"A resposta deve atender ao comando e às evidências do trecho.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"A presença de um verbo no passado basta para classificar qualquer texto como narrativo.","a":false,"why":"É necessário examinar sua organização predominante e sua finalidade.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Um gênero textual pode combinar sequências descritivas, narrativas e argumentativas.","a":true,"why":"Tipo e gênero são classificações de planos distintos.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Notícia e narração são nomes da mesma categoria classificatória.","a":false,"why":"Notícia designa gênero; narração, uma organização textual.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Em 'A biblioteca voltou a abrir', a expressão 'voltou a' pressupõe abertura anterior.","a":true,"why":"A construção indica retomada de uma situação.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Substituir 'alguns servidores' por 'todos os servidores' sempre preserva a informação.","a":false,"why":"A troca altera o alcance da afirmação.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Em 'Estude, mas reserve tempo para descansar', 'mas' introduz contraste.","a":true,"why":"A relação deve ser identificada no contexto, não por simples proximidade.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Toda opinião de uma personagem pode ser atribuída diretamente ao autor do texto.","a":false,"why":"Vozes e posições enunciativas precisam ser distinguidas.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Uma descrição pode caracterizar ambiente sem apresentar progressão de acontecimentos.","a":true,"why":"A caracterização é indício descritivo, não necessariamente narrativo.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Um manual de instruções tende a conter sequências de orientação para agir.","a":true,"why":"A função injuntiva se relaciona à condução de ações.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Toda informação implícita é uma opinião livre do leitor.","a":false,"why":"Implícitos dependem de marcas e relações do texto.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Na argumentação, exemplos podem apoiar uma tese sem se confundirem com ela.","a":true,"why":"Distinguir ponto de vista e sua sustentação evita troca de funções.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"A tese sempre aparece obrigatoriamente na primeira frase do texto.","a":false,"why":"A posição pode ser apresentada ou construída em diferentes lugares.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"O interlocutor e a situação de circulação ajudam a compreender a finalidade do texto.","a":true,"why":"O contexto comunicativo participa da interpretação.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Uma frase gramaticalmente correta sempre mantém o sentido da frase que substitui.","a":false,"why":"Correção gramatical e equivalência semântica são critérios diferentes.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Transformar uma hipótese em certeza pode alterar o sentido de uma reescrita.","a":true,"why":"Modalidade e grau de comprometimento com a afirmação importam.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"A ironia pode ser identificada com segurança sem considerar o contexto.","a":false,"why":"O efeito depende do contraste entre enunciado e avaliação sugerida.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"O comando 'de acordo com o texto' restringe a resposta ao apoio textual pertinente.","a":true,"why":"Conhecimento externo não autoriza substituir o que o texto afirma.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Negação, quantificadores e relações temporais merecem conferência na reescrita.","a":true,"why":"Pequenas mudanças nesses elementos podem modificar a informação.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."}]}},"expected_material":null,"expected_active_enrichments":[],"enrichment":{"id":"0b8c173e-fbb5-5b28-9f6d-7bcb5d833f0b","material_slug":"portugues-leitura-interpretacao-tipologia","version":"2026-10-24-portugues-v1","source_body_sha256":"f2e5d14da9f613f0225b1b49864d2b094bd2f250d4196eabc34c57b4c62ad663","content":{"cases":[{"id":"portugues-complemento-20261024","title":"Informação possível não é inferência obrigatória","scenario":"A biblioteca abriu aos domingos, mas a frequência não aumentou. Uma alternativa conclui que ninguém da cidade gosta de ler.","question":"O texto sustenta a conclusão?","steps":["Localize o dado sobre frequência.","Distinga o resultado observado de uma afirmação universal sobre preferência.","Confira se há apoio para ninguém."],"conclusion":"Não. O texto não permite essa generalização.","pitfall":"Escolher uma regra pelo rótulo ou pela palavra isolada, sem analisar a construção.","variation":{"scenario":"A alternativa diz apenas que a ampliação não se acompanhou do aumento de frequência.","answer":"Esse é o contraste apresentado no enunciado."},"articles":["Análise linguística didática; referências específicas em Fontes"]}],"illustrations":[{"kind":"flow","title":"Roteiro de análise","caption":"Leitura antes da regra isolada.","nodes":["Qual é o comando?","Qual estrutura e qual contexto?","Que regra se aplica?","O sentido foi preservado?"]}]},"sources":[{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","bytes":24352,"sha256":"c9d716829969122d7e63a48e49c127f81993a55dc2c343b0a1fb44889ccce03b","checked_at":"2026-10-25T03:07:02.833711+00:00","key":"gramatica","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","id":"8839c291-1d0d-554e-b02a-72a35ac278b4","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"}],"checked_at":"2026-10-25T03:23:26.419620+00:00","status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-25T03:23:26.419620+00:00"}},{"kind":"new","key":"semantica","topic":{"id":"13a80069-1852-447d-a71b-1c8f2489c487","block_name":"Bloco I","created_at":"2026-09-26T03:57:09.233726+00:00","discipline":"Língua Portuguesa","edition_id":"a982e86c-f18a-47f5-9cf8-f1f8bd2a22ff","topic_text":"Reescrita de frases e parágrafos: significação das palavras; substituição de palavras ou trechos; reorganização de orações e períodos; reescrita em diferentes gêneros e níveis de formalidade. Correspondência oficial conforme o Manual de Redação da Presidência: aspectos gerais, finalidades, linguagem e formato.","topic_order":3,"content_status":"current"},"material":{"id":"7f797101-5d2a-57a1-a7eb-fe6b9f56e693","slug":"portugues-semantica-figuras-linguagem","discipline":"Língua Portuguesa","topic_label":"Semântica e figuras de linguagem","sort_order":11,"title":"Sentido e figuras de linguagem: contexto, palavras e efeitos","summary":"Conceitos essenciais, exemplos próprios, caso resolvido e vinte exercícios comentados. Integra o percurso de Português sem reproduzir capítulos já publicados.","body_md":"## O contexto seleciona o sentido\n\nDenotação é o uso de sentido literal no contexto; conotação envolve associação figurada. Em “A porta de madeira fechou”, porta pode designar objeto físico; em “O curso abriu portas”, a construção sugere oportunidades. Isso não torna o segundo uso um erro gramatical.\n\nSinônimos se aproximam em determinados contextos, sem garantir substituição universal. Antônimos contrastam significados. Polissemia reúne sentidos relacionados de uma palavra; homonímia e paronímia exigem observar identidade ou semelhança de forma e diferenças de significado. Não escolha uma grafia apenas pela semelhança sonora: ratificar é confirmar, retificar é corrigir.\n\n## Figuras e mecanismos\n\n| Figura | Exemplo próprio e efeito |\n| --- | --- |\n| Metáfora | “A notícia foi um raio”: associação sem comparação explicitada |\n| Comparação | “A notícia chegou como um raio”: aproximação expressa |\n| Metonímia | “Li Machado”: autor no lugar da obra, conforme o contexto |\n| Personificação | “A cidade acordou assustada”: traço humano atribuído à cidade |\n| Hipérbole | “Esperei uma eternidade”: intensificação exagerada |\n| Eufemismo | Expressão que atenua uma informação desagradável |\n| Antítese | Aproximação de ideias opostas |\n| Ironia | Descompasso contextual entre o que se diz e a avaliação sugerida |\n\nElipse omite termo recuperável; zeugma retoma por omissão um termo já expresso. Pleonasmo pode ser recurso expressivo ou redundância desnecessária, dependendo da finalidade e do gênero. Não suponha que toda repetição seja vício ou que toda oposição constitua paradoxo.\n\n## Teste de substituição\n\nTrocar “preciso” por “necessitado” funciona em certos contextos, mas não em “o relatório é preciso”, no sentido de exato. Explique o valor da palavra antes da troca e confira o efeito depois dela. Em comunicação oficial, clareza e precisão tendem a desaconselhar figuras que tornem a instrução ambígua; isso não transforma linguagem literária em uso inferior.\n","contest_name":"Polícia Federal — Agente de Polícia Federal — 2025","syllabus_topic_order":3,"source_note":"Elaboração didática própria a partir dos temas dos arquivos fornecidos e de referências institucionais de uso formal e ortografia. Não republica integralmente a redação, publicidade, nomes de docentes ou diagramação das apostilas. Exercícios do acervo têm sua procedência identificada separadamente. Conceitos gramaticais não são apresentados como texto literal de lei. A aplicação a cada concurso depende do edital e de sua data de corte.","legal_basis":[{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal"}],"law_version_checked_at":"2026-10-25T03:23:26.419620+00:00","content_status":"active","reviewed_by":"3ec587f5-0bf5-458d-841e-a19ff9ebbbf6","reviewed_at":"2026-10-25T03:23:26.419620+00:00","quiz":[{"q":"Em 'O curso abriu portas', a construção pode ter sentido figurado de oportunidade.","a":true,"why":"O contexto favorece uma associação não literal."},{"q":"Uma palavra tem obrigatoriamente o mesmo sentido em todos os contextos.","a":false,"why":"A seleção do sentido depende do uso."},{"q":"Em 'A notícia caiu como uma bomba', há comparação explicitada por 'como'.","a":true,"why":"A marca comparativa aproxima as ideias no exemplo proposto."},{"q":"Em 'A notícia foi uma bomba', o uso é metafórico no contexto de grande impacto.","a":true,"why":"A associação dispensa marcador comparativo expresso."},{"q":"Todo sinônimo pode substituir outro termo em qualquer construção sem alterar o sentido.","a":false,"why":"Sinonímia é dependente de contexto e de seleção lexical."},{"q":"Em 'Li Machado', o nome do autor pode representar sua obra.","a":true,"why":"Essa substituição por associação é uma metonímia."},{"q":"Em 'O relógio reclamou da demora', atribui-se comportamento humano ao objeto.","a":true,"why":"A construção exemplifica personificação."},{"q":"Em 'Esperei uma eternidade', pode haver exagero expressivo.","a":true,"why":"No uso comum proposto, a expressão funciona como hipérbole."},{"q":"Retificar e ratificar têm necessariamente o mesmo significado.","a":false,"why":"Retificar é corrigir; ratificar, confirmar."},{"q":"A presença de oposição de ideias é suficiente para afirmar qualquer paradoxo.","a":false,"why":"Antítese e paradoxo exigem análises próprias."},{"q":"Um eufemismo pode atenuar a apresentação de uma informação desagradável.","a":true,"why":"O efeito é de mitigação, conforme o contexto."},{"q":"Toda repetição constitui erro de linguagem.","a":false,"why":"Repetições podem contribuir para coesão ou expressividade."},{"q":"Elipse envolve omissão de termo recuperável pela construção ou contexto.","a":true,"why":"A recuperação distingue omissão interpretável de perda de informação essencial."},{"q":"Zeugma é tratada tradicionalmente como omissão de termo já mencionado.","a":true,"why":"A relação com elemento expresso é relevante nessa classificação."},{"q":"Linguagem figurada é necessariamente inferior à linguagem literal.","a":false,"why":"A adequação depende do gênero e da finalidade."},{"q":"A posição de um adjetivo pode mudar o sentido do grupo nominal.","a":true,"why":"'Velho amigo' e 'amigo velho' permitem leituras diferentes."},{"q":"O sentido de 'preciso' em 'relatório preciso' equivale necessariamente a 'necessitado'.","a":false,"why":"No contexto proposto, preciso pode significar exato."},{"q":"A polissemia envolve sentidos relacionados de uma mesma palavra.","a":true,"why":"A análise distingue esse fenômeno de simples semelhança de forma."},{"q":"A ironia pode produzir avaliação diferente do sentido literal aparente.","a":true,"why":"Ela depende de pistas contextuais, não de uma regra automática."},{"q":"Para garantir clareza em uma instrução técnica, basta escolher palavras rebuscadas.","a":false,"why":"A seleção precisa deve favorecer compreensão, sem ambiguidade desnecessária."}],"flashcards":[{"f":"Em 'O curso abriu portas', a construção pode ter sentido figurado de oportunidade.","b":"Certo. O contexto favorece uma associação não literal."},{"f":"Uma palavra tem obrigatoriamente o mesmo sentido em todos os contextos.","b":"Errado. A seleção do sentido depende do uso."},{"f":"Em 'A notícia caiu como uma bomba', há comparação explicitada por 'como'.","b":"Certo. A marca comparativa aproxima as ideias no exemplo proposto."},{"f":"Em 'A notícia foi uma bomba', o uso é metafórico no contexto de grande impacto.","b":"Certo. A associação dispensa marcador comparativo expresso."}],"legal_review":null,"practice_review":{"version":1,"status":"reviewed","material_slug":"portugues-semantica-figuras-linguagem","subject":"Língua Portuguesa","topic_label":"Semântica e figuras de linguagem","syllabus_topic_id":"13a80069-1852-447d-a71b-1c8f2489c487","checked_at":"2026-10-25T03:23:26.419620+00:00","scope":"Revisão didática assistida dos vinte exercícios. Conceitos e exemplos elaborados para aprendizagem; referências institucionais orientam ortografia e uso formal, sem alegação de transcrição literal de todos os conceitos no manual.","sources":[{"url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","bytes":24352,"sha256":"c9d716829969122d7e63a48e49c127f81993a55dc2c343b0a1fb44889ccce03b","checked_at":"2026-10-25T03:07:02.833711+00:00","key":"gramatica","title":"Senado Federal — Manual de Comunicação: referências de estilo e uso formal","id":"8839c291-1d0d-554e-b02a-72a35ac278b4","status":"vigente","is_official":true,"source_type":"manual","issuer":"Senado Federal"}],"items":[{"q":"Em 'O curso abriu portas', a construção pode ter sentido figurado de oportunidade.","a":true,"why":"O contexto favorece uma associação não literal.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Uma palavra tem obrigatoriamente o mesmo sentido em todos os contextos.","a":false,"why":"A seleção do sentido depende do uso.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Em 'A notícia caiu como uma bomba', há comparação explicitada por 'como'.","a":true,"why":"A marca comparativa aproxima as ideias no exemplo proposto.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Em 'A notícia foi uma bomba', o uso é metafórico no contexto de grande impacto.","a":true,"why":"A associação dispensa marcador comparativo expresso.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Todo sinônimo pode substituir outro termo em qualquer construção sem alterar o sentido.","a":false,"why":"Sinonímia é dependente de contexto e de seleção lexical.","source_url":"https://www12.senado.leg.br/manualdecomunicacao/estilos","origin":"authored_current_language_review","article":"Análise didática do enunciado; consultar a referência normativa específica quando indicada."},{"q":"Em 'Li Machado', o nome do autor pode representar sua obra.","a":true,"why":"Essa substituição por associ